TLM.f("Sancti/07-31",{"officium":"S. Ignatii Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","from":{"Graduale":"Commune/C5","GradualeP":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Philipp 2:10-11"},{"k":"text","la":"In nómine Jesu omne genu flectátur, cœléstium, terréstrium et infernórum: et omnis lingua confiteátur, quia Dóminus Jesus Christus in glória est Dei Patris."},{"k":"ref","la":"Ps 5:12-13"},{"k":"text","la":"Gloriabúntur in te omnes, qui díligunt nomen tuum: quóniam tu benedíces justo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In nómine Jesu omne genu flectátur, cœléstium, terréstrium et infernórum: et omnis lingua confiteátur, quia Dóminus Jesus Christus in glória est Dei Patris."}],"Oratio":[{"k":"text","la":"Deus, qui ad majórem tui nóminis glóriam propagándam, novo per beátum Ignátium subsídio militántem Ecclésiam roborásti: concéde; ut, ejus auxílio et imitatióne certántes in terris, coronári cum ipso mereámur in cœlis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"2 Tim 2:8-10; 3:10-12"},{"k":"text","la":"Caríssime: Memor esto, Dóminum Jesum Christum resurrexísse a mórtuis ex sémine David, secúndum Evangélium meum, in quo labóro usque ad víncula, quasi male óperans: sed verbum Dei non est alligátum. Ideo ómnia sustíneo propter eléctos, ut et ipsi salútem consequántur, quæ est in Christo Jesu, cum glória coelésti. Tu autem assecútus es meam doctrínam, institutiónem, propósitum, fidem, longanimitátem, dilectiónem, patiéntiam, persecutiónes, passiónes: quália mihi facta sunt Antiochíæ, Icónii et Lystris: quales persecutiónes sustínui, et ex ómnibus erípuit me Dóminus. Et omnes, qui pie volunt vívere in Christo Jesu, persecutiónem patiéntur."}],"Graduale":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja"},{"k":"ref","la":"Ja 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 10:1-9"},{"k":"text","la":"In illo témpore: Designávit Dóminus et álios septuagínta duos: et misit illos binos ante fáciem suam in omnem civitátem et locum, quo erat ipse ventúrus. Et dicebat illis: Messis quidem multa, operárii autem pauci. Rogáte ergo Dóminum messis, ut mittat operários in messem suam. Ite: ecce, ego mitto vos sicut agnos inter lupos. Nolíte portáre sácculum neque peram neque calceaménta; et néminem per viam salutavéritis. In quamcúmque domum intravéritis, primum dícite: Pax huic dómui: et si ibi fúerit fílius pacis, requiéscet super illum pax vestra: sin autem, ad vos revertátur. In eádem autem domo manéte, edéntes et bibéntes quæ apud illos sunt: dignus est enim operárius mercéde sua. Nolíte transíre de domo in domum. Et in quamcúmque civitátem intravéritis, et suscéperint vos, manducáte quæ apponúntur vobis: et curáte infírmos, qui in illa sunt, et dícite illis: Appropinquávit in vos regnum Dei."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Adsint, Dómine Deus, oblatiónibus nostris sancti Ignátii benígna suffrágia: ut sacrosáncta mystéria, in quibus omnis sanctitátis fontem constituísti, nos quoque in veritáte sanctíficet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:49"},{"k":"text","la":"Ignem veni míttere in terram: et quid volo, nisi ut accendátur?"}],"Postcommunio":[{"k":"text","la":"Laudis hóstia, Dómine, quam pro sancto Ignátio grátias agentes obtúlimus: ad perpétuam nos majestátis tuæ laudatiónem, ejus intercessióne, pérducat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"9322e46279579ec6":{"t":"Fil 2, 10-11, Ps 5, 12-13\n(Fil 2, 10-11) U ime Isusovo neka se pokloni svako koljeno na nebu, na zemlji i pod zemljom, i svaki jezik neka prizna da je Gospodin Isus Krist u slavi Boga Oca. (Ps 5, 12-13) Dičit će se tobom svi koji ljube tvoje ime jer ti blagoslivljaš pravednika.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Fil 2, 10-11) U ime Isusovo neka se pokloni svako koljeno na nebu, na zemlji i pod zemljom, i svaki jezik neka prizna da je Gospodin Isus Krist u slavi Boga Oca.","kn":"(Fil. 2, 10, U). U Ime se Isusovo poklonilo svako koljeno onih, koji su na nebu i na zemlji d pod zemljom, 1 svaki jezik da prizna na slavu Boga Oca:- Isuis Krist jest Gospodin. (Ps. 5, 12) Dičit će se Tobom svi, boji ljube Ime Tvoje, jer Ti blagosivaš (pravednika. Slava Ocu ... U Ime . . .","knRef":"Kniewald 1942, str. 662–663 (snimka 332) (OCR)"},"8136a3f598146ab6":{"t":"<i>Pomolimo se</i>.\nBože, koji si za širenje veće slave svoga imena po blaženom Ignaciju svoju Crkvu ojačao novom pomoću, daj da njegovim zagovorom i po njegovu primjeru boreći se ovdje na zemlji zaslužimo s njime biti ovjenčani na nebesima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si za raširen je neće slave Imena svoga Crkvu svoju ukrijepio novom pomoću po svetom Ignaclju, podaj, da njegovom pomoću i po njegovu priipij'eru boreći se ovdje na zemlji zavrijedimo s njime biti ovjenčani na nebesima, po G. n.","knRef":"Kniewald 1942, str. 662–663 (snimka 332) (OCR)"},"7d5afdafaf0ae648":{"t":"2 Tim 2, 8-10; 3, 10-12\nČitanje Poslanice bl. Pavla apostola Timoteju. Predragi! Sjeti se da je Gospodin Isus Krist, koji je od Davidova roda, uskrsnuo od mrtvih po momu Evanđelju za koje kao zločinac trpim sve do okova. Ali riječ Božja nije okovana. Zato sve podnosim radi izabranih da i oni s nebeskom slavom postignu spas u Isusu Kristu. A ti si primio moju nauku, način života, odluku, vjeru, ustrajnost, ljubav, strpljivost, progonstvo, trpljenja što su me zadesila u Antiohiji, Ikoniju i Listri. Kakve sam podnio progone i od svih me izbavio Gospodin. A bit će progonjeni svi koji hoće da pobožno žive u Isusu Kristu.","kn":"Čitanje poslanice bi. Pavla apostola Timoteju (II, 2, 8-10. 3, 10-12). Predragi! Sjeti se, da je Gospodin Isus Krist, koji je od Davidova roda, uskrsnuo od mrtvih po momu evanđelju, za koje kao zločinac trpim sve do okova. Ali riječ Božja nije okovana. Zato sve podnosim .radi izabranih, da i oni s nebeskom slavom postignu spas u Isusu Kristu. A ti si primio moju nauku, način života, odluku, vjeru, ustrajnost, ljubav, strpljivost, progonstvo, trpljenja, što su me zadesila u Antiohiji, Ikoniji i Listri; kakve sam podnio progone i od svih me je izbavio Gospodin. A bit će progonjeni svi, koji hoće da ipobožno žive u Isusu Kristu.","knRef":"Kniewald 1942, str. 794–795 (snimka 398) (OCR)"},"929d73ef8c983301":{"t":"Ps 91, 13-14, Ps 91, 3\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik u domu Gospodnjem. (Ps 91, 3) Jutrom naviješta milosrđe tvoje i noću tvoju vjernost.\n\nJak 1, 12\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji nadvlada napast, jer kad bude prokušan, primit će krunu života. <i>Aleluja</i>.","kn":"(Ps. 91, 13, 14). Pravednik i’aste poput paome i libanonskog cedra u domu Gospodnjem. Ra.no jutrom naviješta Tvoje milosrđe i noću Tvoju vjernost.\n\nAleluja, aleiuja. (Jak. 1, 12) Blago čovjeku, koji pretrpi napast, jer će primiti vijenac slave, kad bude prokušan, aleluja.","knRef":"Kniewald 1942, str. 786–787 (snimka 394) (OCR)"},"22b5143a1c0cf786":{"t":"Lk 10, 1-9\nSlijedi sveto Evanđelje po Luki. U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu i posla ih dva po dva pred sobom u svaki grad i mjesto kamo je sam kanio doći. I govorio im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte što imaju jer radnik zaslužuje svoju plaću. Ne prelazite iz kuće u kuću. I u kojigod grad uđete i prime vas, jedite, što postave pred vas. I liječite bolesne koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje!","kn":"t Slijedi sv. evanđelje Po Luki (10, 1-9). U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu 1 posla ih dva po dva pred sobom u svaki gnad i mjesto, kamo je sam kanio doći. I govorio, im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve, da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće, i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte, što imaju, jer radnik zaslužuje svoju plaću.. Ne prelazite iz kuće u kuću. I u kojigođ grad uđete 1 prime vas, jedite, što se. donese pred vas. I liječite bolesne, koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje! .","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"1b673329e89bf6e3":{"t":"Pridružio se našim prinosima, Gospodine, dobrostivi zagovor svetog Ignacija, da presveta otajstva u koja si postavio izvor svake svetosti i nas uistinu posvete.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pridružio se našim prinoBima, Gospodine, dobrostivi zagovor svetog Ignaicija, da, presveta otajstva, u koje si postavio vrutak svake svetosti, i nas uistinu posvete, po G. n.","knRef":"Kniewald 1942, str. 662–663 (snimka 332) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"d412d1929f33c501":{"t":"Ps 109, 3\nOganj dođoh donijeti na svijet, i što bih drugo htio nego da se zapali.","kn":"(Lk. 2, 49). Oganj dođoh donijeti u svijet, i šta hoću, nego da se zapali?","knRef":"Kniewald 1942, str. 662–663 (snimka 332) (OCR)"},"5c28d44631ba805c":{"t":"<i>Pomolimo se</i>.\nŽrtva hvale, Gospodine, što je prinesosmo kao zahvalu o blagdanu svetog Ignacija, dovela nas po njegovu zagovoru onamo gdje ćemo vječno hvaliti tvoje veličanstvo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Žrtva hvale, Gospodine, što je prinesosmo kao zahvalu za sv. Ignacija, dovela nas ipo njegovu zagovoru u vječno hvaljenje Tvoga veličanstva, po G. n.","knRef":"Kniewald 1942, str. 662–663 (snimka 332) (OCR)"}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja"},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}]}}});
